text:
Simulation



Show the simulation code
viewof mode2 = Inputs.radio(["Closed city", "Open city"], {value: "Closed city", label: "City type"})
viewof days = Inputs.range([0, 5], {value: 0, step: 0.5, label: "Remote days per week, d"})
viewof t2 = Inputs.range([500, 4000], {value: 1500, step: 50, label: "Commuting cost on office days, t ($ per mile per yr)"})
viewof y2 = Inputs.range([30000, 120000], {value: 60000, step: 1000, label: "Income, y ($/yr)"})
































Show the simulation code
rA2 = 3000
xbar0 = Math.sqrt(150000 / (Math.PI * 4000))
cbar2 = 60000 - 1500 * xbar0 - rA2                 // outside option = starting residents' consumption
teff = t2 * (1 - days / 5)
before = ({xbar: xbar0, t: 1500, c: cbar2, N: 150})
after = {
  if (mode2 === "Closed city") {
    const c = y2 - teff * xbar0 - rA2;
    return {xbar: xbar0, t: teff, c, N: 150};
  }
  const xbar = teff &gt; 0 ? (y2 - cbar2 - rA2) / teff : Infinity;
  return {xbar, t: teff, c: cbar2, N: Math.PI * 4000 * xbar * xbar / 1000};
}
xmax2 = Math.min(Math.max(before.xbar, isFinite(after.xbar) ? after.xbar : 0) * 1.15, 40)
line2 = s =&gt; d3.range(0, xmax2, xmax2 / 200).map(x =&gt; ({x, r: x &lt;= s.xbar ? rA2 + s.t * (s.xbar - x) : rA2}))
Plot.plot({
  height: 340, marginLeft: 70,
  x: {label: "Distance from the CBD (miles) →", domain: [0, xmax2]},
  y: {label: "↑ Rent ($ per lot per year)", grid: true, zero: true},
  marks: [
    Plot.line(line2(before), {x: "x", y: "r", stroke: "#999", strokeDasharray: "5,4"}),
    Plot.line(line2(after), {x: "x", y: "r", stroke: "#881124", strokeWidth: 3})
  ]
})



































































Show the simulation code
f2c = d3.format(",.0f")
html`${isFinite(after.xbar) ? "" : html`&lt;p&gt;&lt;strong&gt;With no commuting cost at all, an open city has no edge:&lt;/strong&gt; everyone would move in. Set remote days below 5.&lt;/p&gt;`}
&lt;table class="table table-sm readout"&gt;
&lt;thead&gt;&lt;tr&gt;&lt;th&gt;&lt;/th&gt;&lt;th&gt;Before (dashed)&lt;/th&gt;&lt;th&gt;After&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
&lt;tbody&gt;
  &lt;tr&gt;&lt;td&gt;Effective commuting cost ($ per mile per yr)&lt;/td&gt;&lt;td&gt;1,500&lt;/td&gt;&lt;td&gt;${f2c(teff)}&lt;/td&gt;&lt;/tr&gt;
  &lt;tr&gt;&lt;td&gt;City radius (miles)&lt;/td&gt;&lt;td&gt;${before.xbar.toFixed(2)}&lt;/td&gt;&lt;td&gt;${isFinite(after.xbar) ? after.xbar.toFixed(2) : "unbounded"}&lt;/td&gt;&lt;/tr&gt;
  &lt;tr&gt;&lt;td&gt;Population (thousand households)&lt;/td&gt;&lt;td&gt;150&lt;/td&gt;&lt;td&gt;${isFinite(after.N) ? f2c(after.N) : "unbounded"}&lt;/td&gt;&lt;/tr&gt;
  &lt;tr&gt;&lt;td&gt;Rent at the CBD ($ per lot per yr)&lt;/td&gt;&lt;td&gt;${f2c(rA2 + 1500 * before.xbar)}&lt;/td&gt;&lt;td&gt;${isFinite(after.xbar) ? f2c(rA2 + after.t * after.xbar) : "n/a"}&lt;/td&gt;&lt;/tr&gt;
  &lt;tr&gt;&lt;td&gt;Residents' other spending, c ($ per yr)&lt;/td&gt;&lt;td&gt;${f2c(before.c)}&lt;/td&gt;&lt;td&gt;${f2c(after.c)}&lt;/td&gt;&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;`


















Things to try

In a closed city, move remote days from 0 to 2. Who gains: residents or landowners? By how much does rent at the CBD fall?
Make the same change in an open city. Why doesn’t CBD rent change? Where do the gains go instead?
In an open city, set remote days to 4. How much larger does the city get? Where would the new residents come from in real life?
Raise income \(y\) with no remote work. Compare the closed and open cases.
Put remote work and a commuting cost increase together (for example, higher gas prices). Can they cancel out?

Simulation
Change the inputs and watch the rent gradient respond. The dashed grey line shows the starting city so you can compare.



Show the simulation code
viewof mode = Inputs.radio(["Closed city", "Open city"], {value: "Closed city", label: "City type"})
viewof y = Inputs.range([30000, 120000], {value: 60000, step: 1000, label: "Income, y ($/yr)"})
viewof t = Inputs.range([500, 4000], {value: 1500, step: 50, label: "Commuting cost, t ($ per mile per yr)"})
viewof rA = Inputs.range([0, 10000], {value: 3000, step: 250, label: "Agricultural rent, rA ($ per lot per yr)"})
viewof N = Inputs.range([10, 500], {value: 150, step: 5, label: "Population, N (thousand households; closed city only)"})
viewof D = Inputs.range([1000, 8000], {value: 4000, step: 250, label: "Density, D (lots per sq. mile)"})
viewof cbar = Inputs.range([20000, 80000], {value: 51800, step: 100, label: "Outside option, c̄ ($/yr, open city only)"})





















































Show the simulation code
function solve(p) {
  if (p.mode === "Closed city") {
    const xbar = Math.sqrt(p.N * 1000 / (Math.PI * p.D));
    const c = p.y - p.t * xbar - p.rA;
    return {xbar, c, N: p.N, viable: c &gt; 0};
  }
  const xbar = Math.max((p.y - p.cbar - p.rA) / p.t, 0);
  const Nk = Math.PI * p.D * xbar * xbar / 1000;
  return {xbar, c: p.cbar, N: Nk, viable: xbar &gt; 0};
}
base = solve({mode, y: 60000, t: 1500, rA: 3000, N: 150, D: 4000, cbar: 51800})
city = solve({mode, y, t, rA, N, D, cbar})
xmax = Math.max(base.xbar, city.xbar, 1) * 1.15
curve = (s, tt, ra) =&gt; d3.range(0, xmax, xmax / 200).map(x =&gt; ({x, r: x &lt;= s.xbar ? ra + tt * (s.xbar - x) : ra}))
Plot.plot({
  height: 340, marginLeft: 70,
  x: {label: "Distance from the CBD (miles) →", domain: [0, xmax]},
  y: {label: "↑ Rent ($ per lot per year)", grid: true, zero: true},
  marks: [
    Plot.line(curve(base, 1500, 3000), {x: "x", y: "r", stroke: "#999", strokeDasharray: "5,4"}),
    Plot.line(curve(city, t, rA), {x: "x", y: "r", stroke: "#881124", strokeWidth: 3}),
    Plot.ruleX([city.xbar], {stroke: "#881124", strokeOpacity: 0.4}),
    Plot.text([{x: city.xbar, r: rA}], {x: "x", y: "r", text: d =&gt; " edge", dy: -10, textAnchor: "start", fill: "#881124"})
  ]
})














































Show the simulation code
fmt = d3.format(",.0f")
html`${!city.viable ? html`&lt;p&gt;&lt;strong&gt;This city is not viable:&lt;/strong&gt; residents would have nothing left after rent and commuting. Lower the population or commuting cost, or raise income.&lt;/p&gt;` : ""}
&lt;table class="table table-sm readout"&gt;
  &lt;thead&gt;&lt;tr&gt;&lt;th&gt;&lt;/th&gt;&lt;th&gt;Starting city&lt;/th&gt;&lt;th&gt;Your city&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
  &lt;tbody&gt;
    &lt;tr&gt;&lt;td&gt;City radius x̄ (miles)&lt;/td&gt;&lt;td&gt;${base.xbar.toFixed(2)}&lt;/td&gt;&lt;td&gt;${city.xbar.toFixed(2)}&lt;/td&gt;&lt;/tr&gt;
    &lt;tr&gt;&lt;td&gt;Population (thousand households)&lt;/td&gt;&lt;td&gt;${fmt(base.N)}&lt;/td&gt;&lt;td&gt;${fmt(city.N)}&lt;/td&gt;&lt;/tr&gt;
    &lt;tr&gt;&lt;td&gt;Rent at the CBD ($ per lot per year)&lt;/td&gt;&lt;td&gt;${fmt(3000 + 1500 * base.xbar)}&lt;/td&gt;&lt;td&gt;${fmt(rA + t * city.xbar)}&lt;/td&gt;&lt;/tr&gt;
    &lt;tr&gt;&lt;td&gt;Residents' other spending, c ($ per year)&lt;/td&gt;&lt;td&gt;${fmt(base.c)}&lt;/td&gt;&lt;td&gt;${fmt(city.c)}&lt;/td&gt;&lt;/tr&gt;
  &lt;/tbody&gt;
&lt;/table&gt;`


















Things to try

Raise commuting cost \(t\) in a closed city. Which way does the rent line rotate? Why does rent rise downtown but not at the edge? Who pays for the higher commuting cost: residents or landowners?
Make the same change in an open city. Now what happens to the city’s radius and population? Who bears the cost this time?
Raise income \(y\) in each type of city. In which case does rent change, and in which does \(c\) change?
Raise population \(N\) in a closed city. Why does the whole rent line shift up?
Raise density \(D\). What happens to the radius and to rent at the CBD? What kinds of policies change \(D\) in real cities?
